const DOCTOR_BIOS = {
  'mario-r-perez': { photo: 'https://urgimedical.com/assets/img/doctors/dr-mario-2.jpeg', years: '25+', edu: 'Ponce School of Medicine, 1995', training: 'Internal Medicine residency — Jackson Memorial Hospital (Miami) & Jose Gandara Regional Medical University Hospital (Ponce, PR)', boards: 'Board-Certified Internal Medicine',
    bio: { en: ['Dr. Mario R. Perez is board-certified in internal medicine and serves as Medical Director of UrgiMed. After graduating from Ponce School of Medicine in 1995, he completed his internal medicine residency at Jackson Memorial Hospital in Miami and Jose Gandara Regional Medical University Hospital in Ponce, Puerto Rico.', 'Dr. Perez oversees the evaluation and documentation of accident and injury patients across all UrgiMed clinics, coordinating chiropractic, physical therapy, pain management and specialist care into a single treatment plan. He holds additional certifications with the American Academy of Anti-Aging Medicine and the American Society for Laser Medicine and Surgery, with more than 400 hours of postgraduate clinical training.'], es: ['El Dr. Mario R. Perez está certificado en medicina interna y es Director Médico de UrgiMed. Tras graduarse de la Escuela de Medicina de Ponce en 1995, completó su residencia en medicina interna en el Jackson Memorial Hospital de Miami y en el Hospital Universitario Regional Jose Gandara de Ponce, Puerto Rico.', 'El Dr. Perez supervisa la evaluación y documentación de pacientes con lesiones en todas las clínicas UrgiMed, coordinando quiropráctica, terapia física, manejo del dolor y especialistas en un solo plan de tratamiento. Cuenta con certificaciones adicionales de la American Academy of Anti-Aging Medicine y la American Society for Laser Medicine and Surgery, con más de 400 horas de formación clínica de posgrado.'] } },
  'james-manzanares': { photo: 'https://urgimedical.com/assets/img/doctors/dr-james.jpeg', years: '20+', edu: 'Doctor of Medicine', training: 'Orthopaedic Surgery — Mayo Clinic', boards: 'Board-Certified Orthopaedic Surgeon',
    bio: { en: ['Dr. James A. Manzanares is a board-certified orthopaedic surgeon trained at the Mayo Clinic, with a focus on spine surgery and post-injury rehabilitation. At UrgiMed he evaluates accident patients with suspected fractures, disc injuries and joint damage, and determines when conservative treatment is enough and when surgery is the right answer.', 'Most of his patients recover without an operation through a coordinated plan of physical therapy, chiropractic care and pain management. When surgery is needed, it is performed by Dr. Manzanares himself, keeping your whole recovery inside one medical team.'], es: ['El Dr. James A. Manzanares es cirujano ortopédico certificado, formado en Mayo Clinic, con enfoque en cirugía de columna y rehabilitación posterior a lesiones. En UrgiMed evalúa pacientes con sospecha de fracturas, lesiones de disco y daño articular, y determina cuándo basta el tratamiento conservador y cuándo la cirugía es la respuesta correcta.', 'La mayoría de sus pacientes se recuperan sin operación mediante un plan coordinado de terapia física, quiropráctica y manejo del dolor. Cuando se necesita cirugía, la realiza el propio Dr. Manzanares, manteniendo toda su recuperación dentro de un mismo equipo médico.'] } },
  'alexandra-carrer': { photo: 'https://urgimedical.com/assets/img/doctors/dr-alexandra.png', years: '15+', edu: 'SUNY Downstate Medical Center, MD 2006', training: 'Orthopaedic Surgery residency — SUNY Downstate · Spine fellowship — UC San Francisco', boards: 'Board-Certified Orthopaedic Surgeon, FAAOS',
    bio: { en: ['Dr. Alexandra Carrer is a board-certified orthopaedic spine surgeon and Fellow of the American Academy of Orthopaedic Surgeons. She earned her MD at SUNY Downstate Medical Center, completed her orthopaedic surgery residency there and a spine fellowship at the University of California San Francisco. She has practiced at a Level I trauma center and was recognized by the American Health Council as “Best in Medicine.”', 'A former competitive athlete and martial artist, Dr. Carrer came to orthopaedics through her own sports injuries, which shaped her belief in rehabilitation and non-surgical care whenever possible. She has published peer-reviewed research and book chapters and is a member of AOSpine and the Society of Lateral Access Surgery. Dr. Carrer is fluent in Spanish and French.'], es: ['La Dra. Alexandra Carrer es cirujana ortopédica de columna certificada y Fellow de la American Academy of Orthopaedic Surgeons. Obtuvo su título de médico en SUNY Downstate Medical Center, donde completó su residencia en cirugía ortopédica, y realizó un fellowship de columna en la Universidad de California San Francisco. Ha ejercido en un centro de trauma Nivel I y fue reconocida por el American Health Council como “Best in Medicine”.', 'Exatleta competitiva y artista marcial, la Dra. Carrer llegó a la ortopedia por sus propias lesiones deportivas, lo que formó su convicción en la rehabilitación y el tratamiento no quirúrgico siempre que sea posible. Ha publicado investigaciones y capítulos de libros, y es miembro de AOSpine. Habla español y francés con fluidez.'] } },
  'abraham-josiah-fura': { photo: 'https://urgimedical.com/assets/img/doctors/dr-abraham-2.jpeg', years: '15+', edu: 'Niagara University, BS Biology (summa cum laude) · NYCOM, DO 2010 (top 3%)', training: 'Anesthesiology residency — Walter Reed National Military Medical Center · Multidisciplinary Pain Management fellowship — University of Rochester Medical Center', boards: 'Board-Certified Anesthesiology & Pain Medicine',
    bio: { en: ['Dr. Abraham J. Fura is a board-certified anesthesiologist and pain medicine physician. He completed his fellowship in Multidisciplinary Pain Management at the University of Rochester Medical Center, where he performed more than 2,500 interventional procedures in a single year, and his anesthesiology residency at Walter Reed National Military Medical Center.', 'Dr. Fura served as a U.S. Army officer from 2006 to 2018, reaching the rank of Major, and led obstetrical anesthesia and quality-improvement programs at Carl R. Darnall Army Medical Center. At UrgiMed he provides nerve blocks, joint and spine injections and minimally invasive pain procedures for accident and work-injury patients.'], es: ['El Dr. Abraham J. Fura es anestesiólogo y médico del dolor certificado. Completó su fellowship en Manejo Multidisciplinario del Dolor en la Universidad de Rochester, donde realizó más de 2,500 procedimientos intervencionistas en un solo año, y su residencia en anestesiología en el Walter Reed National Military Medical Center.', 'El Dr. Fura sirvió como oficial del Ejército de EE. UU. de 2006 a 2018, alcanzando el rango de Mayor, y dirigió programas de anestesia obstétrica y mejora de calidad en el Carl R. Darnall Army Medical Center. En UrgiMed realiza bloqueos nerviosos, inyecciones articulares y de columna y procedimientos mínimamente invasivos para pacientes con lesiones.'] } },
  'gregory-schwaid': { photo: 'https://urgimedical.com/assets/img/doctors/dr-gregory.jpg', years: '20+', edu: 'Doctor of Osteopathic Medicine', training: 'General Preventive Medicine', boards: 'Board-Certified General Preventive Medicine',
    bio: { en: ['Dr. Gregory Schwaid is a Medical Director at UrgiMed, board-certified in general preventive medicine. He focuses on the first-visit evaluation of accident patients: identifying injuries that are easy to miss in the days after a crash, ordering the right imaging and testing, and documenting Emergency Medical Condition status within Florida’s 14-day PIP window.', 'Dr. Schwaid works closely with UrgiMed’s chiropractors, therapists and specialists so that each patient leaves the first appointment with a clear plan and complete paperwork for their insurer or attorney.'], es: ['El Dr. Gregory Schwaid es Director Médico en UrgiMed, certificado en medicina preventiva general. Se enfoca en la evaluación de primera visita de pacientes accidentados: identificar lesiones fáciles de pasar por alto en los días posteriores al choque, ordenar las imágenes y pruebas correctas y documentar la Condición Médica de Emergencia dentro del plazo de 14 días del PIP.', 'El Dr. Schwaid trabaja de cerca con los quiroprácticos, terapeutas y especialistas de UrgiMed para que cada paciente salga de su primera cita con un plan claro y el papeleo completo para su aseguradora o abogado.'] } },
  'allamm-morales': { photo: 'https://urgimedical.com/assets/img/doctors/dr-morales.jpg', years: '20+', edu: 'Instituto Superior de Ciencias Médicas de Villa Clara, Cuba, 1992', training: 'Neurology — University of South Florida College of Medicine · Internal Medicine — Hospital Episcopal San Lucas', boards: 'Neurology & Psychiatry',
    bio: { en: ['Dr. Allamm Morales is a neurologist with more than 20 years of experience, trained at the University of South Florida College of Medicine after earning his medical degree in 1992. He has been affiliated with Wuesthoff Medical Center Rockledge, Parrish Medical Center and the Florida Neurology Institute.', 'At UrgiMed, Dr. Morales evaluates concussion, post-traumatic headaches, nerve injuries and the psychological effects of trauma after car accidents and falls, and performs nerve conduction testing on site. He sees patients in English and Spanish.'], es: ['El Dr. Allamm Morales es neurólogo con más de 20 años de experiencia, formado en la Facultad de Medicina de la Universidad del Sur de Florida tras obtener su título de médico en 1992. Ha estado afiliado al Wuesthoff Medical Center Rockledge, al Parrish Medical Center y al Florida Neurology Institute.', 'En UrgiMed, el Dr. Morales evalúa conmociones, dolores de cabeza postraumáticos, lesiones nerviosas y los efectos psicológicos del trauma tras accidentes de auto y caídas, y realiza pruebas de conducción nerviosa en el sitio. Atiende en inglés y español.'] } },
};

const FAQ = [
  { q: { en: 'Do I need a referral?', es: '¿Necesito una referencia?' }, a: { en: 'No. Call the clinic nearest you or book online and we will see you the same day in most cases.', es: 'No. Llame a la clínica más cercana o reserve en línea y en la mayoría de los casos le atendemos el mismo día.' } },
  { q: { en: 'What is Florida’s 14-day rule?', es: '¿Qué es la regla de 14 días de Florida?' }, a: { en: 'Your PIP (Personal Injury Protection) auto insurance only covers treatment if you see a doctor within 14 days of the accident. The rule is still in effect in 2026. Do not wait for pain to “settle”.', es: 'Su seguro PIP (Protección de Lesiones Personales) solo cubre el tratamiento si ve a un médico dentro de 14 días del accidente. La regla sigue vigente en 2026. No espere a que el dolor “se calme”.' } },
  { q: { en: 'Do you take PIP?', es: '¿Aceptan PIP?' }, a: { en: 'Yes. We bill your PIP directly, determine your Emergency Medical Condition (EMC) status and handle the paperwork with your insurer.', es: 'Sí. Facturamos directamente a su PIP, determinamos su Condición Médica de Emergencia (EMC) y gestionamos el papeleo con su aseguradora.' } },
  { q: { en: 'What if I don’t have a lawyer?', es: '¿Y si no tengo abogado?' }, a: { en: 'You do not need one to be treated. If you decide to hire one later, we provide complete records; we work with attorneys across Florida and can accept a Letter of Protection.', es: 'No necesita uno para recibir tratamiento. Si decide contratar uno después, entregamos expedientes completos; trabajamos con abogados en toda Florida y aceptamos Cartas de Protección.' } },
  { q: { en: 'Can I come the same day?', es: '¿Puedo venir el mismo día?' }, a: { en: 'Yes. Call before 5 PM and we will do our best to see you today. Walk-ins are welcome during opening hours.', es: 'Sí. Llame antes de las 5 PM y haremos lo posible por atenderle hoy. Puede llegar sin cita en horario de atención.' } },
  { q: { en: 'What should I bring?', es: '¿Qué debo traer?' }, a: { en: 'A photo ID, your auto or health insurance card, the police / crash report if you have it, and any photos of the accident or injuries.', es: 'Identificación con foto, su tarjeta de seguro de auto o salud, el reporte policial del accidente si lo tiene y fotos del accidente o las lesiones.' } },
  { q: { en: 'Do you speak Spanish?', es: '¿Hablan español?' }, a: { en: 'Yes — se habla español at every UrgiMed clinic.', es: 'Sí, se habla español en todas las clínicas UrgiMed.' } },
  { q: { en: 'What if I was a passenger?', es: '¿Y si yo era pasajero?' }, a: { en: 'Passengers are covered too, usually under the driver’s PIP or your own policy. We help you sort out which applies.', es: 'Los pasajeros también están cubiertos, normalmente bajo el PIP del conductor o su propia póliza. Le ayudamos a determinar cuál aplica.' } },
  { q: { en: 'Is parking free?', es: '¿El estacionamiento es gratis?' }, a: { en: 'Yes, free parking at every location.', es: 'Sí, estacionamiento gratuito en todas las clínicas.' } },
  { q: { en: 'Do you handle workers’ compensation?', es: '¿Manejan compensación laboral?' }, a: { en: 'Yes. We complete DWC forms, provide work-status notes and report to the adjuster after every visit.', es: 'Sí. Completamos formularios DWC, entregamos notas de estado laboral e informamos al ajustador después de cada visita.' } },
];

